class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        res = 0
        pref = {}
        pref2 = {}

        for i in range(20, -1, -1):
            pref.clear()
            pref2.clear()

            for a in nums:
                p = a >> i
                if p in pref:
                    pref2[p] = max(pref2[p], a)
                    pref[p] = min(pref[p], a)
                else:
                    pref[p] = a
                    pref2[p] = a

            for x in pref:
                y = res ^ 1 ^ x
                if x >= y and y in pref:
                    if pref[x] <= pref2[y] * 2:
                        res |= 1

        return res
